=== storage-key.ts
     1	// The storage key grammar, alone in its own module on purpose.
     2	//
     3	// The production payload decoder (protocol-client) must validate storage keys,
     4	// so whatever module it imports this from is in every resuming page's eager
     5	// chunk. The rest of the storage surface — the slot symbol, the slot-entry key
     6	// derivation, the no-flash attribute name — is client-storage-only and is
     7	// demand-loaded with the storage plane. Keeping them in one module put all of
     8	// it in the eager chunk, because a lazy chunk importing from an eager module
     9	// pins that module's exports there.
    10	//
    11	// A storage key is either an author's verbatim explicit key or a derived
    12	// markless:<identifier>. Permissive but structurally safe: letters, digits, and
    13	// $ _ : . - only (no whitespace, quotes, brackets, or control characters). The
    14	// colon admits the markless: namespace; the resume decoder uses this to reject
    15	// malformed payloads.
    16	const STORAGE_KEY_PATTERN = /^[A-Za-z0-9$_:.-]+$/;
    17	
    18	export function isValidStorageKey(value: string): boolean {
    19		return STORAGE_KEY_PATTERN.test(value);
    20	}
=== storage-slot.ts
     1	export { isValidStorageKey } from './storage-key.ts';
     2	
     3	export const STORAGE_SLOT_SYMBOL_KEY = 'tsrx.storage/1';
     4	
     5	// The no-flash <html> attribute name for a driver key. Derived keys contain a
     6	// colon (markless:theme) which is not a clean attribute name, so any character
     7	// outside [A-Za-z0-9-] collapses to a hyphen: markless:theme -> data-markless-theme,
     8	// theme -> data-theme. Used identically by the seed script and the storage plane
     9	// so both write the same attribute.
    10	export function storageAttributeName(driverKey: string): string {
    11		return `data-${driverKey.replace(/[^A-Za-z0-9-]+/g, '-')}`;
    12	}
    13	
    14	export type StorageSeedMetadata = {
    15		readonly slotKey: string;
    16		readonly driverKey: string;
    17		readonly fallback: string;
    18	};
    19	
    20	export function storageSlotEntryKey(moduleId: string, key: string): string {
    21		return `${moduleId}#${key}`;
    22	}
    23	
    24	export function storageSlotEntryKeyFromGraphNodeId(graphNodeId: string): string {
    25		return graphNodeId.startsWith('storage:') ? graphNodeId.slice('storage:'.length) : graphNodeId;
    26	}
    27	
    28	export function createStorageSeedMetadata(
    29		moduleId: string,
    30		driverKey: string,
    31		fallback: string,
    32	): StorageSeedMetadata {
    33		return {
    34			slotKey: storageSlotEntryKey(moduleId, driverKey),
    35			driverKey,
    36			fallback,
    37		};
    38	}
    39	
    40	// The seed's slotKey MUST anchor to the same graphNodeId the wake-time override
    41	// (payload-graph-construct) derives its lookup key from — otherwise a warm slot
    42	// is written under one key and read under another, and the component silently
    43	// falls back. Derive it from the graphNodeId so they match by construction.
    44	export function createStorageSeedMetadataFromGraphNodeId(
    45		graphNodeId: string,
    46		driverKey: string,
    47		fallback: string,
    48	): StorageSeedMetadata {
    49		return {
    50			slotKey: storageSlotEntryKeyFromGraphNodeId(graphNodeId),
    51			driverKey,
    52			fallback,
    53		};
    54	}
