     5	export function validateStorageRecords(
     6		payload: ProtocolStatePayload,
     7		invalid: (type: 'markless/state', message: string) => Error,
     8	): void {
     9		if (payload.version !== STORAGE_PROTOCOL_VERSION) return;
    10		if (!Array.isArray(payload.storage))
    11			throw invalid('markless/state', 'Invalid markless/state storage: expected array.');
    12		for (const entry of payload.storage) {
    13			if (
    14				typeof entry !== 'object' ||
    15				entry === null ||
    16				typeof entry.key !== 'string' ||
    17				!isValidStorageKey(entry.key) ||
    18				!payload.cells.some((cell) => cell.graphNodeId === entry.graphNodeId)
    19			)
    20				throw invalid(
    21					'markless/state',
    22					'Invalid markless/state storage: invalid storage record.',
    23				);
    24		}
    25	}
=== protocol-validation-storage.ts
     1	import {
     2		decodePayloadScriptsWithVersion,
     3		invalidPayloadShapeError,
     4		type DecodedPayloadScripts,
     5		type EncodedPayloadScripts,
     6	} from './protocol-validation.ts';
     7	import { STORAGE_PROTOCOL_VERSION } from './protocol-constants.ts';
     8	import { isValidStorageKey } from './storage-key.ts';
     9	
    10	export * from './protocol-validation.ts';
    11	
    12	export function decodePayloadScripts(input: EncodedPayloadScripts): DecodedPayloadScripts {
    13		const decoded = decodePayloadScriptsWithVersion(input, true);
    14		if (decoded.state.version !== STORAGE_PROTOCOL_VERSION) return decoded;
    15		const cellIds = new Set(decoded.state.cells.map((cell) => cell.graphNodeId));
    16		const storage = (decoded.state as unknown as Record<string, unknown>).storage;
    17		if (!Array.isArray(storage))
    18			throw invalidPayloadShapeError(
    19				'markless/state',
    20				'Invalid markless/state payload: expected storage array.',
    21			);
    22		for (const [index, entry] of storage.entries()) {
    23			const context = `markless/state storage[${index}]`;
    24			if (typeof entry !== 'object' || entry === null || Array.isArray(entry))
    25				throw invalidPayloadShapeError(
    26					'markless/state',
    27					`Invalid ${context}: expected object.`,
    28				);
    29			const record = entry as Record<string, unknown>;
    30			if (typeof record.graphNodeId !== 'string')
    31				throw invalidPayloadShapeError(
    32					'markless/state',
    33					`Invalid ${context}: expected graphNodeId string.`,
    34				);
    35			if (typeof record.key !== 'string')
    36				throw invalidPayloadShapeError(
    37					'markless/state',
    38					`Invalid ${context}: expected key string.`,
    39				);
    40			if (!cellIds.has(record.graphNodeId))
    41				throw invalidPayloadShapeError(
    42					'markless/state',
    43					`Invalid ${context}: graphNodeId must match a state cell.`,
    44				);
    45			if (!isValidStorageKey(record.key))
    46				throw invalidPayloadShapeError(
    47					'markless/state',
    48					`Invalid ${context}: key must be a verbatim key or a derived markless:<identifier>.`,
    49				);
    50		}
    51		return decoded;
    52	}

