1	import { GRAPH_VALUE_PROTOCOL_VERSION } from './value-constants.ts';
2	
3	export type SerializedPrimitive =
4		| null
5		| string
6		| number
7		| boolean
8		| { readonly $type: 'undefined' }
9		| { readonly $type: 'bigint'; readonly value: string };
10	
11	export type SerializedSlot =
12		| SerializedPrimitive
13		| { readonly $ref: number }
14		| { readonly $type: 'date'; readonly value: string }
15		| { readonly $type: 'regexp'; readonly source: string; readonly flags: string }
16		| { readonly $type: 'url'; readonly value: string };
17	
18	export type SerializedRecord =
19		| {
20				readonly id: number;
21				readonly type: 'object';
22				readonly fields: ReadonlyArray<readonly [string, SerializedSlot]>;
23		  }
24		| {
25				readonly id: number;
26				readonly type: 'array';
27				readonly items: ReadonlyArray<SerializedSlot>;
28		  }
29		| {
30				readonly id: number;
31				readonly type: 'map';
32				readonly entries: ReadonlyArray<readonly [SerializedSlot, SerializedSlot]>;
33		  }
34		| {
35				readonly id: number;
36				readonly type: 'set';
37				readonly values: ReadonlyArray<SerializedSlot>;
38		  }
39		| {
40				readonly id: number;
41				readonly type: 'date';
42				readonly value: string;
43		  }
44		| {
45				readonly id: number;
46				readonly type: 'regexp';
47				readonly source: string;
48				readonly flags: string;
49		  }
50		| {
51				readonly id: number;
52				readonly type: 'url';
53				readonly value: string;
54		  }
55		| {
56				readonly id: number;
57				readonly type: 'array-buffer';
58				readonly bytes: ReadonlyArray<number>;
59		  }
60		| {
61				readonly id: number;
62				readonly type: 'typed-array';
63				readonly arrayType: TypedArrayName;
64				readonly buffer: SerializedSlot;
65				readonly byteOffset: number;
66				readonly length: number;
67		  }
68		| {
69				readonly id: number;
70				readonly type: 'data-view';
71				readonly buffer: SerializedSlot;
72				readonly byteOffset: number;
73				readonly byteLength: number;
74		  };
75	
76	export type TypedArrayName =
77		| 'Int8Array'
78		| 'Uint8Array'
79		| 'Uint8ClampedArray'
80		| 'Int16Array'
81		| 'Uint16Array'
82		| 'Int32Array'
83		| 'Uint32Array'
84		| 'Float32Array'
85		| 'Float64Array'
86		| 'BigInt64Array'
87		| 'BigUint64Array';
88	
89	export type SerializedGraphPayload = {
90		readonly version: typeof GRAPH_VALUE_PROTOCOL_VERSION;
91		readonly root: SerializedSlot;
92		readonly records: ReadonlyArray<SerializedRecord>;
93	};
94	
95	export type SerializationDiagnostic = {
96		readonly code: 'MARKLESS_SERIALIZE_UNSUPPORTED_VALUE';
97		readonly severity: 'error';
98		readonly phase: 'serialization';
99		readonly title: 'Cannot serialize graph state value';
100		readonly path: ReadonlyArray<string>;
101		readonly statePath: string;
102		readonly valueKind: string;
103		readonly message: string;
104		readonly why: string;
105		readonly suggestions: ReadonlyArray<{ readonly message: string }>;
106		readonly docsUrl: string;
107	};
108	
109	export type SerializationResult =
110		| {
111				readonly ok: true;
112				readonly payload: SerializedGraphPayload;
113				readonly diagnostics: readonly [];
114		  }
115		| {
116				readonly ok: false;
117				readonly diagnostics: ReadonlyArray<SerializationDiagnostic>;
118		  };
119	
120	export { deserializeGraphValue } from './value-decode.ts';
121	
122	export function serializeGraphValue(value: unknown): SerializationResult {
123		const diagnostics: SerializationDiagnostic[] = [];
124		const seen = new WeakMap<object, number>();
125		const records: SerializedRecord[] = [];
126	
127		const root = encodeSlot(value, [], seen, records, diagnostics);
128		if (root === undefined || diagnostics.length > 0) {
129			return {
130				ok: false,
131				diagnostics,
132			};
133		}
134	
135		return {
136			ok: true,
137			payload: {
138				version: GRAPH_VALUE_PROTOCOL_VERSION,
139				root,
140				records,
141			},
142			diagnostics: [],
143		};
144	}
145	
146	function encodeSlot(
147		value: unknown,
148		path: ReadonlyArray<string>,
149		seen: WeakMap<object, number>,
150		records: SerializedRecord[],
151		diagnostics: SerializationDiagnostic[],
152	): SerializedSlot | undefined {
153		if (value === null) return null;
154		if (typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean') {
155			return value;
156		}
157		if (typeof value === 'undefined') return { $type: 'undefined' };
158		if (typeof value === 'bigint') return { $type: 'bigint', value: String(value) };
159	
160		if (typeof value === 'function' || typeof value === 'symbol') {
161			diagnostics.push(unsupportedDiagnostic(value, path));
162			return undefined;
163		}
164	
165		if (!isObject(value)) {
166			diagnostics.push(unsupportedDiagnostic(value, path));
167			return undefined;
168		}
169	
170		if (value instanceof Date) {
171			const existingId = seen.get(value);
172			if (existingId !== undefined) return { $ref: existingId };
173	
174			const id = records.length;
175			seen.set(value, id);
176			records.push({ id, type: 'date', value: value.toISOString() });
177			return { $ref: id };
178		}
179		if (value instanceof RegExp) {
180			const existingId = seen.get(value);
181			if (existingId !== undefined) return { $ref: existingId };
182	
183			const id = records.length;
184			seen.set(value, id);
185			records.push({ id, type: 'regexp', source: value.source, flags: value.flags });
186			return { $ref: id };
187		}
188		if (value instanceof URL) {
189			const existingId = seen.get(value);
190			if (existingId !== undefined) return { $ref: existingId };
191	
192			const id = records.length;
193			seen.set(value, id);
194			records.push({ id, type: 'url', value: value.toString() });
195			return { $ref: id };
196		}
197	
198		if (value instanceof ArrayBuffer) {
199			const existingId = seen.get(value);
200			if (existingId !== undefined) return { $ref: existingId };
201	
202			const id = records.length;
203			seen.set(value, id);
204			records.push({
205				id,
206				type: 'array-buffer',
207				bytes: [...new Uint8Array(value)],
208			});
209			return { $ref: id };
210		}
211	
212		const arrayType = typedArrayName(value);
213		if (arrayType) {
214			const existingId = seen.get(value);
215			if (existingId !== undefined) return { $ref: existingId };
216	
217			const id = records.length;
218			seen.set(value, id);
219			records.push({
220				id,
221				type: 'typed-array',
222				arrayType,
223				buffer: encodeArrayBufferViewBuffer(value, path, seen, records, diagnostics),
224				byteOffset: typedArrayByteOffset(value),
225				length: typedArrayLength(value),
226			});
227			return { $ref: id };
